<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {ChevronLeft,ChevronRight,Search,Settings2,ShieldCheck} from 'lucide-vue-next'
import {date,notify,type Row} from '../lib'
import {riskApi} from '../riskApi'
import {rememberList,toggleSort} from '../listState'
import ListPager from './ListPager.vue'
import SortHeader from './SortHeader.vue'
import Modal from './Modal.vue'
import RiskAlertSettings from './RiskAlertSettings.vue'
const props=defineProps<{mode:string}>()
const data=ref<Row>({items:[],traffic:[],summary:{}}),q=ref(''),start=ref(''),end=ref(''),category=ref(''),state=ref('pending'),page=ref(1),loading=ref(false),busy=ref(false),error=ref(''),detail=ref<Row|null>(null),settings=ref(false),auto=ref(false)
const applied=ref<Row>({state:props.mode==='alerts'?'pending':''})
const size=ref(10),sortBy=ref(props.mode==='traffic'?'requests':'last_seen'),sortDir=ref('desc')
rememberList('risk-'+props.mode,{q,start,end,category,state,page,size,sortBy,sortDir,auto,applied})
function sort(field:string){toggleSort(field,sortBy,sortDir,page)}
watch([page,size,sortBy,sortDir],()=>void load())
const pages=computed(()=>Math.max(1,Math.ceil((data.value.total||0)/size.value)))
const categories:Row={login:'登录安全',access:'访问异常',limit:'频率限制',application:'订单异常',finance:'积分安全',admin:'管理操作'}
const operations:Row={login:'登录',logout:'退出登录',auth:'账户验证',submit:'提交注册订单',query:'查询',export:'账号导出',write:'业务操作',cancel:'取消订单',keys:'密钥管理',admin:'管理操作',risk:'风控管理',scan:'异常检查'}
let controller:AbortController|undefined,timer:ReturnType<typeof setInterval>|undefined,lastRefresh=0
async function load(){controller?.abort();const request=new AbortController();controller=request;loading.value=true;error.value='';try{const result=await riskApi('/monitor?'+new URLSearchParams({...applied.value,offset:String((page.value-1)*size.value),limit:String(size.value),sort_by:sortBy.value,sort_dir:sortDir.value,view:props.mode}),'GET',undefined,request.signal);if(controller===request){data.value=result;if(page.value>pages.value){page.value=pages.value;void load()}}}catch(e){if(controller===request&&(e as Error).name!=='AbortError')error.value=(e as Error).message}finally{if(controller===request){loading.value=false;lastRefresh=Date.now()}}}
function apply(){if(start.value&&end.value&&start.value>end.value){error.value='结束日期不能早于开始日期';return}applied.value={q:q.value,start:start.value,end:end.value,category:props.mode==='alerts'?category.value:'',state:props.mode==='alerts'?state.value:''};page.value=1;void load()}
function reset(){q.value='';start.value='';end.value='';category.value='';state.value='pending';apply()}
async function run(path:string,message:string){if(busy.value)return;busy.value=true;error.value='';try{await riskApi(path,'POST',{});notify(message);detail.value=null;await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>{void load();timer=setInterval(()=>{if(auto.value&&!loading.value&&!busy.value&&!settings.value&&!detail.value&&document.visibilityState==='visible'&&Date.now()-lastRefresh>=(data.value.refresh_seconds||15)*1000)void load()},1000)})
onUnmounted(()=>{controller?.abort();clearInterval(timer)})
defineExpose({refresh:load,loading})
</script>
<template>
 <section class="risk-diagnostics">
  <div class="risk-section-heading"><div><h2>{{mode==='alerts'?'业务告警':'访问统计'}}</h2><p>{{mode==='alerts'?'查看订单排队、交付和积分核对中发现的问题。':'按客户与操作汇总已记录的业务请求，可按客户、日期筛选。'}}</p></div><div class="actions"><template v-if="mode==='alerts'"><button class="btn secondary" @click="settings=true"><Settings2 :size="15"/>告警设置</button><button class="btn primary" :disabled="busy" @click="run('/scan','异常检查已完成')">{{busy?'正在检查…':'立即检查'}}</button></template></div></div>
  <p v-if="error" class="alert danger" role="alert">{{error}}</p>
  <p v-if="data.monitoring_enabled===false" class="risk-notice">业务告警记录已关闭，当前显示历史记录。</p>
  <form class="risk-query" @submit.prevent="apply"><label class="risk-search">搜索<div class="search-box"><Search :size="16"/><input v-model="q" placeholder="客户、IP 或订单号" maxlength="200" aria-label="搜索业务记录"/></div></label><template v-if="mode==='alerts'"><label>告警分类<select v-model="category"><option value="">全部分类</option><option v-for="(name,key) in categories" :key="key" :value="key">{{name}}</option></select></label><label>处理状态<select v-model="state"><option value="">全部状态</option><option value="pending">待核查</option><option value="resolved">已核查</option></select></label></template><div class="risk-query-row"><label>开始日期<input v-model="start" type="date"/></label><span class="risk-date-divider">至</span><label>结束日期<input v-model="end" type="date"/></label><div class="risk-query-actions"><button class="btn primary" :disabled="loading"><Search :size="15"/>查询</button><button type="button" class="btn secondary" :disabled="loading" @click="reset">重置</button></div></div></form>
  <div class="risk-list-meta"><span v-if="mode==='alerts'">共 <b>{{data.total||0}}</b> 条告警 · 最近检查 {{date(data.last_scan)}}</span><span v-else>请求 {{data.summary.requests||0}} 次 · 错误 {{data.summary.errors||0}} 次 · 平均 {{data.summary.average_ms||0}} ms</span><label class="risk-auto"><input v-model="auto" type="checkbox"/>每 {{data.refresh_seconds||15}} 秒刷新</label></div>
  <div class="table-scroll"><table v-if="mode==='alerts'" class="risk-table"><thead><tr><SortHeader label="告警" field="category" :sort-by="sortBy" :sort-dir="sortDir" @sort="sort"/><SortHeader label="客户 / IP" field="account" :sort-by="sortBy" :sort-dir="sortDir" @sort="sort"/><SortHeader label="最近发生" field="last_seen" :sort-by="sortBy" :sort-dir="sortDir" @sort="sort"/><SortHeader label="次数" field="occurrences" :sort-by="sortBy" :sort-dir="sortDir" @sort="sort"/><SortHeader label="状态" field="resolved_at" :sort-by="sortBy" :sort-dir="sortDir" @sort="sort"/><th>操作</th></tr></thead><tbody><tr v-for="e in data.items" :key="e.id"><td data-label="告警" class="risk-wide"><div class="risk-event-title"><span class="risk-level" :class="e.severity">{{e.severity==='critical'?'高风险':e.severity==='warning'?'需关注':'一般'}}</span><button class="risk-event-link" @click="detail=e">{{categories[e.category]||e.category}}</button></div><p class="risk-description" :title="e.message">{{e.message}}</p></td><td data-label="客户 / IP"><b class="risk-customer">{{e.user_name||e.account||'未登录访问'}}</b><small v-if="e.user_name">{{e.account}}</small><small class="mono">{{e.source_ip||'—'}}</small></td><td data-label="最近发生"><time>{{date(e.last_seen)}}</time></td><td data-label="次数">{{e.occurrences}}</td><td data-label="状态"><span class="risk-status" :class="{resolved:e.resolved_at}">{{e.resolved_at?'已核查':'待核查'}}</span></td><td data-label="操作"><div class="risk-row-actions"><button class="text-btn" @click="detail=e">详情</button><button v-if="!e.resolved_at" class="text-btn" :disabled="busy" @click="run('/events/'+e.id+'/resolve','已标记核查')">标记核查</button></div></td></tr></tbody></table>
   <table v-else class="risk-table risk-traffic-table"><thead><tr><SortHeader label="客户" field="email" :sort-by="sortBy" :sort-dir="sortDir" @sort="sort"/><SortHeader label="操作 / 渠道" field="operation" :sort-by="sortBy" :sort-dir="sortDir" @sort="sort"/><SortHeader label="访问次数" field="requests" :sort-by="sortBy" :sort-dir="sortDir" @sort="sort"/><SortHeader label="错误次数" field="errors" :sort-by="sortBy" :sort-dir="sortDir" @sort="sort"/><SortHeader label="拦截次数" field="blocked" :sort-by="sortBy" :sort-dir="sortDir" @sort="sort"/><SortHeader label="平均响应" field="average_ms" :sort-by="sortBy" :sort-dir="sortDir" @sort="sort"/></tr></thead><tbody><tr v-for="(r,i) in data.traffic" :key="i"><td data-label="客户"><b class="risk-customer">{{r.user_name||r.email||'未登录访问'}}</b><small v-if="r.user_name">{{r.email}}</small></td><td data-label="操作 / 渠道">{{operations[r.operation]||r.operation}}<small>{{r.channel==='api'?'API':'网页'}}{{r.key_name?' · '+r.key_name:''}}</small></td><td data-label="访问次数">{{r.requests}}</td><td data-label="错误次数">{{r.errors}}</td><td data-label="拦截次数">{{r.blocked}}</td><td data-label="平均响应">{{r.average_ms}} ms</td></tr></tbody></table>
   <div v-if="!(mode==='alerts'?data.items:data.traffic).length" class="risk-empty"><ShieldCheck :size="30"/><strong>{{loading?'正在加载…':error?'记录加载失败':'没有符合条件的记录'}}</strong></div>
  </div>
  <ListPager v-model:page="page" v-model:size="size" :total="data.total||0" :loading="loading"/>
  <Modal v-if="detail" title="业务告警详情" @close="detail=null"><div class="risk-dialog"><h3>{{detail.message}}</h3><dl><dt>告警分类</dt><dd>{{categories[detail.category]||detail.category}}</dd><dt>客户</dt><dd>{{detail.user_name||detail.account||'—'}}</dd><dt>IP 地址</dt><dd>{{detail.source_ip||'—'}}</dd><dt>关联记录</dt><dd class="mono">{{detail.target||'—'}}</dd><dt>首次发生</dt><dd>{{date(detail.created_at)}}</dd><dt>最近发生</dt><dd>{{date(detail.last_seen)}}</dd><dt>触发次数</dt><dd>{{detail.occurrences}}</dd><dt>响应</dt><dd>{{detail.status?'HTTP '+detail.status:'定时检查'}}</dd></dl><div v-if="!detail.resolved_at" class="risk-dialog-actions"><button class="btn primary" :disabled="busy" @click="run('/events/'+detail.id+'/resolve','已标记核查')">标记已核查</button></div></div></Modal>
  <Modal v-if="settings" title="业务告警设置" wide @close="settings=false"><RiskAlertSettings @saved="settings=false;load()"/></Modal>
 </section>
</template>
<style scoped>.risk-auto{display:flex;flex-direction:row;align-items:center;gap:7px;margin:0;font-size:11px}.risk-auto input{width:14px;height:14px;accent-color:var(--green)}</style>
